update season_pass_rewards set enabled=false,updated_at=now()where tier='free';
alter table season_pass_rewards drop constraint if exists season_pass_rewards_tier_check;alter table season_pass_rewards add constraint season_pass_rewards_tier_check check(tier in('adventurer','legendary'))not valid;
alter table player_season_pass add column if not exists tier text not null default'none',add column if not exists purchased_at timestamptz,add column if not exists upgraded_at timestamptz;
update player_season_pass set tier=case when legendary_owned then'legendary'when adventurer_owned then'adventurer'else'none'end;
alter table player_season_pass drop constraint if exists player_season_pass_tier_check;alter table player_season_pass add constraint player_season_pass_tier_check check(tier in('none','adventurer','legendary'));
create or replace function get_season_pass_dashboard(p_telegram_id bigint)returns jsonb language plpgsql security definer set search_path=public as $$declare u uuid;s season_pass_seasons%rowtype;p player_season_pass%rowtype;begin select id into u from game_players where telegram_id=p_telegram_id;select*into s from season_pass_seasons where active and now()between start_at and end_at;if u is null or s.id is null then raise exception'SEASON_NOT_AVAILABLE';end if;insert into player_season_pass(user_id,season_id,tier)values(u,s.id,'none')on conflict do nothing;select*into p from player_season_pass where user_id=u and season_id=s.id;return jsonb_build_object('season',jsonb_build_object('id',s.id,'name',s.name,'endsAt',s.end_at,'levels',s.levels,'xpPerLevel',s.xp_per_level,'adventurerPriceTon',s.adventurer_price_ton,'legendaryPriceTon',s.legendary_price_ton,'upgradePriceTon',greatest(0,s.legendary_price_ton-s.adventurer_price_ton)),'player',jsonb_build_object('xp',p.xp,'level',least(s.levels,floor(p.xp/s.xp_per_level)::int+1),'tier',p.tier,'adventurerOwned',p.tier in('adventurer','legendary'),'legendaryOwned',p.tier='legendary'),'rewards',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'level',r.level,'tier',r.tier,'type',r.reward_type,'code',r.reward_code,'amount',r.amount,'title',r.title,'claimed',c.id is not null,'unlocked',r.level<=least(s.levels,floor(p.xp/s.xp_per_level)::int+1)and(r.tier='adventurer'and p.tier in('adventurer','legendary')or r.tier='legendary'and p.tier='legendary'))order by r.level,case r.tier when'adventurer'then 1 else 2 end),'[]')from season_pass_rewards r left join season_pass_claims c on c.reward_id=r.id and c.user_id=u where r.season_id=s.id and r.enabled and r.tier in('adventurer','legendary')));end$$;
create or replace function create_season_pass_order(p_telegram_id bigint,p_tier text,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=public as $$declare u uuid;s season_pass_seasons%rowtype;p player_season_pass%rowtype;o season_pass_orders%rowtype;price numeric;address text;begin if p_tier not in('adventurer','legendary')then raise exception'INVALID_PASS_TIER';end if;select id into u from game_players where telegram_id=p_telegram_id;select*into s from season_pass_seasons where active and now()between start_at and end_at;if u is null or s.id is null then raise exception'SEASON_NOT_AVAILABLE';end if;insert into player_season_pass(user_id,season_id,tier)values(u,s.id,'none')on conflict do nothing;select*into p from player_season_pass where user_id=u and season_id=s.id for update;if p.tier='legendary'or p_tier='adventurer'and p.tier='adventurer'then raise exception'PASS_ALREADY_OWNED';end if;select*into o from season_pass_orders where idempotency_key=p_idempotency_key;if o.id is not null then return jsonb_build_object('id',o.id,'paymentAddress',o.payment_address,'amountNano',o.amount_nano,'amountTon',o.price_ton,'paymentComment',o.payment_comment,'expiresAt',o.expires_at);end if;price:=case when p_tier='adventurer'then s.adventurer_price_ton when p.tier='adventurer'then s.legendary_price_ton-s.adventurer_price_ton else s.legendary_price_ton end;if price<=0 then raise exception'INVALID_PASS_PRICE';end if;address:=wallet_hot_address();insert into season_pass_orders(user_id,season_id,tier,price_ton,amount_nano,payment_address,payment_comment,idempotency_key)values(u,s.id,p_tier,price,round(price*1000000000)::text,address,'forge_pass:'||gen_random_uuid(),p_idempotency_key)returning*into o;return jsonb_build_object('id',o.id,'paymentAddress',o.payment_address,'amountNano',o.amount_nano,'amountTon',o.price_ton,'paymentComment',o.payment_comment,'expiresAt',o.expires_at);end$$;
create or replace function confirm_season_pass_order(p_order_id uuid,p_tx_hash text,p_amount_nano text)returns void language plpgsql security definer set search_path=public as $$declare o season_pass_orders%rowtype;p player_season_pass%rowtype;begin select*into o from season_pass_orders where id=p_order_id for update;if o.id is null then raise exception'ORDER_NOT_FOUND';end if;if o.status='activated'then return;end if;if o.expires_at<now()or o.amount_nano<>p_amount_nano then raise exception'INVALID_OR_EXPIRED_PAYMENT';end if;if exists(select 1 from season_pass_orders where tx_hash=p_tx_hash and id<>o.id)then raise exception'TX_ALREADY_USED';end if;select*into p from player_season_pass where user_id=o.user_id and season_id=o.season_id for update;if p.tier='legendary'or o.tier='adventurer'and p.tier='adventurer'then raise exception'PASS_ALREADY_OWNED';end if;update season_pass_orders set status='paid',tx_hash=p_tx_hash,paid_at=now()where id=o.id;update player_season_pass set tier=case when o.tier='legendary'then'legendary'else'adventurer'end,adventurer_owned=true,legendary_owned=o.tier='legendary'or legendary_owned,purchased_at=coalesce(purchased_at,now()),upgraded_at=case when o.tier='legendary'and p.tier='adventurer'then now()else upgraded_at end,updated_at=now()where user_id=o.user_id and season_id=o.season_id;update season_pass_orders set status='activated',activated_at=now()where id=o.id;end$$;
create or replace function claim_season_pass_reward(p_telegram_id bigint,p_reward_id uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare u game_players%rowtype;r season_pass_rewards%rowtype;p player_season_pass%rowtype;s season_pass_seasons%rowtype;egg uuid;key text;begin select*into u from game_players where telegram_id=p_telegram_id for update;select*into r from season_pass_rewards where id=p_reward_id and enabled and tier in('adventurer','legendary');if r.id is null then raise exception'REWARD_LOCKED';end if;select*into s from season_pass_seasons where id=r.season_id and active;select*into p from player_season_pass where user_id=u.id and season_id=s.id for update;if u.id is null or s.id is null or p.tier='none'or r.level>least(s.levels,floor(p.xp/s.xp_per_level)::int+1)then raise exception'REWARD_LOCKED';end if;if r.tier='adventurer'and p.tier not in('adventurer','legendary')or r.tier='legendary'and p.tier<>'legendary'then raise exception'PASS_NOT_OWNED';end if;key:='season_reward:'||u.id||':'||r.id;insert into season_pass_claims(user_id,reward_id,idempotency_key)values(u.id,r.id,key)on conflict do nothing;if not found then return get_season_pass_dashboard(p_telegram_id);end if;if r.reward_type='fc'then update game_players set forge_coins=forge_coins+r.amount,updated_at=now()where id=u.id;elsif r.reward_type='pvp_ticket'then update game_players set pvp_tickets=pvp_tickets+r.amount::int,updated_at=now()where id=u.id;elsif r.reward_type='pet_egg'then select id into egg from pet_eggs where slug=r.reward_code;insert into player_pet_inventory(user_id,item_type,item_id,quantity)values(u.id,'egg',egg,r.amount::int)on conflict(user_id,item_type,(coalesce(item_id,'00000000-0000-0000-0000-000000000000'::uuid)))do update set quantity=player_pet_inventory.quantity+excluded.quantity,updated_at=now();elsif r.reward_type='pet_food'then insert into player_pet_inventory(user_id,item_type,quantity)values(u.id,'food',r.amount::int)on conflict(user_id,item_type,(coalesce(item_id,'00000000-0000-0000-0000-000000000000'::uuid)))do update set quantity=player_pet_inventory.quantity+excluded.quantity,updated_at=now();else insert into player_inventory(user_id,item_type,item_code,quantity)values(u.id,r.reward_type,coalesce(r.reward_code,r.reward_type),r.amount::int)on conflict(user_id,item_type,item_code)do update set quantity=player_inventory.quantity+excluded.quantity,updated_at=now();end if;return get_season_pass_dashboard(p_telegram_id);end$$;
drop function if exists admin_update_season_reward(uuid,int,text,text,numeric,text,boolean);create function admin_update_season_reward(p_reward_id uuid,p_tier text,p_level int,p_type text,p_code text,p_amount numeric,p_title text,p_enabled boolean)returns void language plpgsql security definer set search_path=public as $$begin if p_tier not in('adventurer','legendary')or p_level<1 or p_amount<=0 or p_type not in('fc','hero_chest','pet_egg','pet_food','fragments','pvp_ticket','skin')then raise exception'INVALID_REWARD_CONFIG';end if;update season_pass_rewards set tier=p_tier,level=p_level,reward_type=p_type,reward_code=nullif(trim(p_code),''),amount=p_amount,title=trim(p_title),enabled=p_enabled,updated_at=now()where id=p_reward_id and tier in('adventurer','legendary');if not found then raise exception'REWARD_NOT_FOUND';end if;end$$;
revoke all on function get_season_pass_dashboard(bigint),create_season_pass_order(bigint,text,text),confirm_season_pass_order(uuid,text,text),claim_season_pass_reward(bigint,uuid),admin_update_season_reward(uuid,text,int,text,text,numeric,text,boolean)from public,anon,authenticated;grant execute on function get_season_pass_dashboard(bigint),create_season_pass_order(bigint,text,text),confirm_season_pass_order(uuid,text,text),claim_season_pass_reward(bigint,uuid),admin_update_season_reward(uuid,text,int,text,text,numeric,text,boolean)to service_role;
